.submit-btn {
  display: block;
  width: 100%;
  margin-top: 1.75rem;
  padding: 0.85rem 1.5rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-field);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
  letter-spacing: 0.01em;
