.submit-btn:hover { background: var(--accent-hover); }
.submit-btn:active { background: var(--accent-active); transform: scale(0.99); }
.submit-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.submit-btn:disabled { opacity: 0.55; cursor: not-allowed; transform: none; }

