  display: none;
  margin-top: 1.5rem;
  padding: 1rem 1.25rem;
  border-radius: var(--radius-field);
  font-weight: 600;
  font-size: 0.95rem;
  line-height: 1.5;
  border: 1.5px solid;
}
.result-banner[data-state="partial"] {
  background: rgba(91, 141, 238, 0.1);
  border-color: var(--accent);
  color: var(--accent-hover);
}
.result-banner[data-state="pass"] {
  background: rgba(76, 175, 130, 0.1);
  border-color: var(--text-correct);
  color: var(--text-correct);
}
.result-banner[data-state="fail"] {
  background: rgba(224, 92, 110, 0.1);
  border-color: var(--text-incorrect);
  color: var(--text-incorrect);
