  border-radius: var(--radius-card);
  padding: 2rem;
  box-shadow: var(--shadow-card);
}

/* ── Form fields (question wrappers) ── */
.form-field {
  margin-bottom: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--border-default);
