  padding: 0.15rem 0.55rem;
  border-radius: 99px;
  margin-bottom: 0.5rem;
}

/* ── Options list ── */
.options-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

/* ── Checkbox option ── */
.option-label {
