AssistantMessageToolRequest(name='create', tool_call_id='tooluse_WOdpIdmeKn6ivW6exebLzO', arguments={'file_text': '/* ── Quiz data ── */
const QUESTIONS = [
  {
    id: "q1",
    number: "Question 1",
    text: "Which of the following are statically typed languages?",
    helpText: "Select all that apply. In statically typed languages, variable types are checked at compile time rather than at runtime.",
    options: [
      { value: "python",     label: "Python" },
      { value: "typescript", label: "TypeScript" },
      { value: "java",       label: "Java" },
      { value: "rust",       label: "Rust" },
    ],
    correctValues: ["typescript", "java", "rust"],
  },
  {
    id: "q2",
    number: "Question 2",
    text: "Which programming languages were originally created at Bell Labs?",
    options: [
      { value: "c",      label: "C" },
      { value: "go",     label: "Go" },
      { value: "awk",    label: "AWK" },
      { value: "python", label: "Python" },
    ],
    correctValues: ["c", "awk"],
  },
  {
    id: "q3",
    number: "Question 3",
    text: "Which of the following languages include automatic garbage collection?",
    options: [
      { value: "c",    label: "C" },
      { value: "java", label: "Java" },
      { value: "go",   label: "Go" },
      { value: "rust", label: "Rust" },
    ],
    correctValues: ["java", "go"],
  },
];

/* ── Component: Option ── */
function Option({ questionId, value, label }) {
  const id = `${questionId}-${value}`;
  return `
    <li>
      <label class="option-label" for="${id}">
        <input
          type="checkbox"
          id="${id}"
          name="${questionId}"
          value="${value}"
        />
        <span class="option-text">${label}</span>
      </label>
    </li>`;
}

/* ── Component: FormField (Question) ── */
function FormField({ id, number, text, helpText, options }) {
  const helpId   = helpText ? `${id}-help` : null;
  const feedbackId = `${id}-feedback`;

  const helpHTML = helpText
    ? `<span id="${helpId}" class="field-help">${helpText}</span>`
    : "";

  const optionsHTML = options
    .map((opt) => Option({ questionId: id, ...opt }))
    .join("");

  return `
    <div class="form-field" data-question="${id}">
      <fieldset aria-describedby="${[helpId, feedbackId].filter(Boolean).join(" ")}">
        <legend>
          <span class="q-number">${number}</span><br>
          ${text}
        </legend>
        ${helpHTML}
        <ul class="options-list" role="group">
          ${optionsHTML}
        </ul>
      </fieldset>
      <p id="${feedbackId}" class="field-feedback" aria-live="polite"></p>
